() => {
  const [open, setOpen] = React.useState(false)
  const toggle = () => setOpen(!open)
  return (
    <AnchoredOverlay
      open={open}
      onOpen={toggle}
      onClose={toggle}
      renderAnchor={(props) => (
        <button type="button" {...props}>
          toggle overlay
        </button>
      )}
    >
      <ActionList role="menu">
        <ActionList.Item role="menuitem">
          Use your arrow keys
          <ActionList.TrailingVisual>↓</ActionList.TrailingVisual>
        </ActionList.Item>
        <ActionList.Item role="menuitem">
          keep going
          <ActionList.TrailingVisual>↓</ActionList.TrailingVisual>
        </ActionList.Item>
        <ActionList.Item role="menuitem">
          more more
          <ActionList.TrailingVisual>↓</ActionList.TrailingVisual>
        </ActionList.Item>
        <ActionList.Divider />
        <ActionList.Item variant="danger" role="menuitem">
          now go up!
          <ActionList.TrailingVisual>↑</ActionList.TrailingVisual>
        </ActionList.Item>
      </ActionList>
    </AnchoredOverlay>
  )
}

() => {
  const [assignees, setAssignees] = React.useState(users.slice(0, 1))
  const toggleAssignee = (assignee: (typeof users)[number]) => {
    const assigneeIndex = assignees.findIndex((a) => a.login === assignee.login)
    if (assigneeIndex === -1) setAssignees([...assignees, assignee])
    else setAssignees(assignees.filter((_, index) => index !== assigneeIndex))
  }
  return (
    <ActionList
      selectionVariant="multiple"
      role="menu"
      showDividers
      aria-label="Reviewers"
    >
      <ActionList.Group>
        <ActionList.GroupHeading>Everyone</ActionList.GroupHeading>
        {users.slice(2).map((user) => (
          <ActionList.Item
            role="menuitemcheckbox"
            key={user.login}
            selected={Boolean(
              assignees.find((assignee) => assignee.login === user.login),
            )}
            aria-checked={Boolean(
              assignees.find((assignee) => assignee.login === user.login),
            )}
            onSelect={() => toggleAssignee(user)}
          >
            <ActionList.LeadingVisual>
              <Avatar src={`https://github.com/${user.login}.png`} />
            </ActionList.LeadingVisual>
            {user.login}
            <ActionList.Description>{user.name}</ActionList.Description>
          </ActionList.Item>
        ))}
      </ActionList.Group>
    </ActionList>
  )
}

